package studio.jiayu.neoagent;
import android.app.Activity;import android.os.*;import android.graphics.*;import android.view.*;import android.view.accessibility.*;import android.widget.*;import android.accessibilityservice.*;import org.json.*;import java.io.*;import java.net.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;

/** Emulator-only synthetic UI and in-process fake HTTPS; never reads accounts or calls a provider. */
final class RuntimeContracts {
 final Activity activity;final ControlService service;final Handler main=new Handler(Looper.getMainLooper());
 final CountDownLatch firstRequest=new CountDownLatch(1),releaseOld=new CountDownLatch(1);final AtomicInteger requests=new AtomicInteger(),clicks=new AtomicInteger();
 volatile boolean manualSeen,newRevision;volatile String firstRevision="";int passed;Button target;
 RuntimeContracts(Activity a){activity=a;service=ControlService.instance;}
 static void start(Activity a){LinearLayout box=new LinearLayout(a);box.setOrientation(1);box.setPadding(32,140,32,32);Button button=new Button(a);button.setText("稳定测试按钮");box.addView(button);a.setContentView(box);RuntimeContracts test=new RuntimeContracts(a);test.target=button;button.setOnClickListener(v->test.clicks.incrementAndGet());new Handler().postDelayed(()->new Thread(test::run).start(),1500);}
 void yes(boolean ok,String name)throws Exception{if(!ok)throw new Exception(name);passed++;}
 void await(java.util.function.BooleanSupplier condition,long ms)throws Exception{long end=SystemClock.elapsedRealtime()+ms;while(SystemClock.elapsedRealtime()<end){if(condition.getAsBoolean())return;Thread.sleep(40);}throw new Exception("Timed out waiting for owned runtime");}
 int node(ControlService.Observation o,String label,boolean editable)throws Exception{JSONArray list=o.json.getJSONArray("nodes");for(int i=0;i<list.length();i++){JSONObject n=list.getJSONObject(i);if(editable?n.optBoolean("editable"):label.equals(n.optString("text")))return n.getInt("id");}throw new Exception("Missing synthetic node");}
 Action tap(int id)throws Exception{return new Action(new JSONObject().put("action","tap").put("id",id));}
 void reject(ControlService.Observation source,long g,Action action)throws Exception{boolean blocked=false;try{service.execute(action,g,source);}catch(ControlService.UiChangedException expected){blocked=true;}yes(blocked,"Stale GUI action accepted");}
 Config config(){Config c=new Config();c.key="LOCAL_FIXTURE";c.endpoint="https://example.invalid";c.vision=true;c.maxSteps=12;return c;}
 void run(){JSONObject result=new JSONObject();String oldGrant="";try{oldGrant=new Vault(activity).get(RoutineAccess.KEY);new RoutineAccess(activity).approve(config(),java.util.Collections.singletonList(activity.getPackageName()));
  yes(service!=null&&service.connected&&!service.busy(),"Service unavailable");
  long g=service.ui(()->{service.allowed=activity.getPackageName();service.running=true;service.paused=false;service.runConfig=config();service.generation=service.ownership.start();return service.generation;});
  ControlService.Observation old=service.observe(false,g),fresh=service.observe(false,g);reject(old,g,tap(node(old,"稳定测试按钮",false)));yes(clicks.get()==0,"Stale ref emitted a gesture");
  service.ui(()->{target.setText("已替换的测试按钮");return true;});reject(fresh,g,tap(node(fresh,"稳定测试按钮",false)));yes(clicks.get()==0,"Changed label emitted a gesture");
  ControlService.Observation current=service.observe(false,g);service.execute(tap(node(current,"已替换的测试按钮",false)),g,current);yes(clicks.get()==1,"Fresh native tap failed");ControlService.Observation stable=service.observe(false,g);service.ui(()->{Button unrelated=new Button(activity);unrelated.setText("无关动态推荐已更新");((LinearLayout)target.getParent()).addView(unrelated);return true;});Thread.sleep(200);service.execute(tap(node(stable,"已替换的测试按钮",false)),g,stable);yes(clicks.get()==2,"Unrelated UI update blocked unchanged target");service.stop("语义引用测试结束");
  URL.setURLStreamHandlerFactory(protocol->protocol.equals("https")?new URLStreamHandler(){protected URLConnection openConnection(URL url){return new ModelContracts.Fake(url){public InputStream getInputStream(){try{
   int turn=requests.incrementAndGet();JSONObject request=new JSONObject(body.toString("UTF-8"));Object content=request.getJSONArray("messages").getJSONObject(1).get("content");String text=content instanceof JSONArray?((JSONArray)content).getJSONObject(0).getString("text"):String.valueOf(content);if(content instanceof JSONArray&&((JSONArray)content).length()<3)throw new Exception("Missing visual observation");JSONObject state=new JSONObject(text.substring(text.indexOf("当前界面：")+5));JSONArray nodes=state.getJSONArray("nodes");int input=-1;for(int i=0;i<nodes.length();i++)if(nodes.getJSONObject(i).optBoolean("editable"))input=nodes.getJSONObject(i).getInt("id");String response;
   if(turn==1){firstRevision=state.getString("observation_id");firstRequest.countDown();releaseOld.await(12,TimeUnit.SECONDS);response=new JSONObject().put("action","type").put("id",input).put("text","过期回复不得输入").toString();}
   else if(turn==2){manualSeen=text.contains("手动更改");newRevision=!firstRevision.equals(state.getString("observation_id"));response=new JSONObject().put("action","type").put("id",input).put("text","交还后新输入").toString();}
   else response="{\"action\":\"finish\",\"message\":\"本地测试输入完成\"}";
   return new ByteArrayInputStream(new JSONObject().put("choices",new JSONArray().put(new JSONObject().put("message",new JSONObject().put("content",response)))).toString().getBytes("UTF-8"));
  }catch(Exception failure){return new ByteArrayInputStream("{}".getBytes());}}};}}:null);
  service.ui(()->{service.start(config(),activity.getPackageName(),"保留目标并从交还后的当前输入框继续");return true;});
  yes(firstRequest.await(12,TimeUnit.SECONDS),"No initial native observation");String originalGoal=service.task,run=service.runId;long originalLease=service.generation;
  service.ui(()->{service.pauseForUser();return true;});yes(service.paused&&!service.running&&!service.ownership.accepts(originalLease),"Takeover did not revoke lease");
  yes(!service.start(config(),activity.getPackageName(),"不得覆盖暂停目标"),"Paused goal replaced");releaseOld.countDown();CompletableFuture<Boolean> drained=new CompletableFuture<>();service.worker.submit(()->drained.complete(true));yes(drained.get(5,TimeUnit.SECONDS)&&service.actions==0&&service.paused,"Late response acted or ended pause");
  service.ui(()->{AccessibilityNodeInfo root=service.getRootInActiveWindow(),input=root.findFocus(AccessibilityNodeInfo.FOCUS_INPUT);if(input==null){for(int i=0;i<root.getChildCount();i++){AccessibilityNodeInfo child=root.getChild(i);if(child!=null&&child.isEditable())input=child;}}if(input==null){java.util.ArrayDeque<AccessibilityNodeInfo> queue=new java.util.ArrayDeque<>();queue.add(root);while(!queue.isEmpty()){AccessibilityNodeInfo n=queue.removeFirst();if(n.isEditable()){input=n;break;}for(int i=0;i<n.getChildCount();i++){AccessibilityNodeInfo child=n.getChild(i);if(child!=null)queue.add(child);}}}if(input==null)throw new Exception("No owned input");Bundle args=new Bundle();args.putCharSequence(AccessibilityNodeInfo.ACTION_ARGUMENT_SET_TEXT_CHARSEQUENCE,"手动更改");if(!input.performAction(AccessibilityNodeInfo.ACTION_SET_TEXT,args))throw new Exception("Cannot change synthetic input");return true;});
  yes(service.ui(service::resumeFromUser),"Cannot hand back");await(()->!service.busy(),15000);yes(manualSeen&&newRevision,"Resume reused old observation");yes(service.task.equals(originalGoal)&&service.runId.equals(run)&&service.actions==1&&requests.get()==3,"Resume changed goal or replayed an action");
  boolean visible=service.ui(()->{AccessibilityNodeInfo root=service.getRootInActiveWindow();for(AccessibilityNodeInfo n:root.findAccessibilityNodeInfosByText("交还后新输入"))if(n.isVisibleToUser()&&"交还后新输入".contentEquals(n.getText()))return true;return false;});yes(visible,"Actual text differs from successful receipt");
  capsule();JSONObject monitor=service.runtimeHealth.snapshot();yes(monitor.getLong("heartbeat_age_ms")>=0&&monitor.getLong("heartbeat_age_ms")<2000,"No independent live heartbeat");result.put("success",true);
 }catch(Throwable error){try{result.put("success",false).put("failure",error.getMessage()).put("where",java.util.Arrays.toString(error.getStackTrace()).substring(0,Math.min(900,java.util.Arrays.toString(error.getStackTrace()).length())));}catch(Exception ignored){}}
 finally{try{new Vault(activity).put(RoutineAccess.KEY,oldGrant);}catch(Exception ignored){}releaseOld.countDown();if(service!=null)service.stop("运行时合成回归结束");try{result.put("passed",passed).put("real_network_calls",0).put("third_party_apps",0).put("mock_requests",requests.get()).put("new_observation_after_resume",newRevision);try(FileOutputStream out=activity.openFileOutput("runtime-contracts.json",0)){out.write(result.put("sampledAt",System.currentTimeMillis()).toString(2).getBytes("UTF-8"));}}catch(Exception ignored){}main.post(activity::finish);}
 }
 void capsule()throws Exception{
  android.content.SharedPreferences prefs=activity.getSharedPreferences("ui",0);boolean hadX=prefs.contains("controlBarX"),hadY=prefs.contains("controlBarY");float oldX=prefs.getFloat("controlBarX",1),oldY=prefs.getFloat("controlBarY",.5f);prefs.edit().remove("controlBarX").remove("controlBarY").commit();
  try{service.ui(()->{service.allowed=activity.getPackageName();service.runConfig=config();service.running=true;service.paused=false;service.generation=service.ownership.start();service.pauseForUser();return true;});Thread.sleep(700);Rect original=service.ui(()->service.controlBar.bounds());yes(original!=null&&Math.abs(original.centerY()-service.screenMetrics().heightPixels/2)<service.dp(12),"Capsule default is not centered");
   int[] point=service.ui(()->{View button=service.controlBar.view.getChildAt(1);int[] child=new int[2],parent=new int[2];button.getLocationOnScreen(child);service.controlBar.view.getLocationOnScreen(parent);return new int[]{original.left+child[0]-parent[0]+button.getWidth()/2,original.top+child[1]-parent[1]+button.getHeight()/2};});
   CompletableFuture<Boolean> gesture=new CompletableFuture<>();service.ui(()->{Path path=new Path();path.moveTo(point[0],point[1]);path.lineTo(Math.max(service.dp(30),point[0]-service.dp(100)),Math.min(service.screenMetrics().heightPixels-service.dp(100),point[1]+service.dp(110)));boolean accepted=service.dispatchGesture(new GestureDescription.Builder().addStroke(new GestureDescription.StrokeDescription(path,0,650)).build(),new AccessibilityService.GestureResultCallback(){public void onCompleted(GestureDescription d){gesture.complete(true);}public void onCancelled(GestureDescription d){gesture.complete(false);}},new Handler(Looper.getMainLooper()));if(!accepted)gesture.complete(false);return true;});yes(gesture.get(4,TimeUnit.SECONDS),"Owned capsule drag was cancelled");Thread.sleep(250);Rect moved=service.ui(()->service.controlBar.bounds());yes(service.paused&&!service.running&&moved!=null&&(Math.abs(moved.left-original.left)>service.dp(15)||Math.abs(moved.top-original.top)>service.dp(15)),"Button drag clicked hand-back or failed to move");service.showOverlay();Thread.sleep(700);Rect restored=service.ui(()->service.controlBar.bounds());yes(restored!=null&&Math.abs(restored.left-moved.left)<service.dp(3)&&Math.abs(restored.top-moved.top)<service.dp(3),"Capsule position did not survive recreation moved="+moved+" restored="+restored+" normalized="+prefs.getFloat("controlBarX",-1)+","+prefs.getFloat("controlBarY",-1));
  }finally{android.content.SharedPreferences.Editor edit=prefs.edit();if(hadX)edit.putFloat("controlBarX",oldX);else edit.remove("controlBarX");if(hadY)edit.putFloat("controlBarY",oldY);else edit.remove("controlBarY");edit.commit();}
 }
}
